package com.hbm.machine.radiolysis;
import java.util.List;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class RadiolysisContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");private static final DeferredRegister<RecipeType<?>> TYPES=DeferredRegister.create(Registries.RECIPE_TYPE,"hbm");private static final DeferredRegister<RecipeSerializer<?>> SERIALIZERS=DeferredRegister.create(Registries.RECIPE_SERIALIZER,"hbm");
 public static final DeferredBlock<RadiolysisBlock> BLOCK=BLOCKS.register("machine_radiolysis",RadiolysisBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem(BLOCK);
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<RadiolysisBlockEntity>> ENTITY=ENTITIES.register("radiolysis",()->BlockEntityType.Builder.of(RadiolysisBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<RadiolysisPort>> PORT=ENTITIES.register("radiolysis_port",()->BlockEntityType.Builder.of(RadiolysisPort::new,BLOCK.get()).build(null));
 public static final DeferredHolder<MenuType<?>,MenuType<RadiolysisMenu>> MENU=MENUS.register("radiolysis",()->new MenuType<>((IContainerFactory<RadiolysisMenu>)RadiolysisMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static final DeferredHolder<RecipeType<?>,RecipeType<RadiolysisRecipe>> TYPE=TYPES.register("radiolysis",()->new RecipeType<RadiolysisRecipe>(){});public static final DeferredHolder<RecipeSerializer<?>,RadiolysisRecipe.Serializer> SERIALIZER=SERIALIZERS.register("radiolysis",RadiolysisRecipe.Serializer::new);
 public static ResourceLocation id(String name){return ResourceLocation.fromNamespaceAndPath("hbm",name);}
 public static void register(IEventBus bus){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);TYPES.register(bus);SERIALIZERS.register(bus);bus.addListener(RadiolysisContent::capabilities);RadiolysisRecipeConfig.register();}
 private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,PORT.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));}
 public static List<ItemStack> creativeStacks(String tab){return tab.equals("machine")?List.of(new ItemStack(ITEM.get())):List.of();}
 private RadiolysisContent(){}
}
